const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
let task: Task;
try { task = normalizeTaskKeyOrder(parseYaml(readFileSync(yamlPath, "utf-8")) as Record<string, unknown>); }
catch (e) { return { won: false, reason: "push_rejected", details: `yaml read failed: ${gitErrDetails(e)}` }; }

// Duplicate-claim guard: if the task is already "in_progress", another
// fix agent claimed this cycle first (claimFixTask sets status to in_progress
